export function AnchorUnavailableDates() {
  const now = today(getLocalTimeZone());

  const isDateUnavailable = (date: DateValue, anchorDate: CalendarDate | null) => {
    return anchorDate != null && Math.abs(date.compare(anchorDate)) > 7;
